declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN','VERIFICADOR']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detalle de pago — Franky</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:820px;margin:auto;padding:82px 14px 34px}.back{display:inline-flex;gap:6px;align-items:center;text-decoration:none;color:#315b78;font-weight:800;font-size:13px;margin-bottom:14px}.head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:16px}.head h1{margin:0;font-size:30px;letter-spacing:-.03em}.sub{color:#64748b;font-size:13px;margin-top:5px}.badge{display:inline-block;padding:6px 9px;border-radius:999px;font-size:11px;font-weight:900}.ok{background:#dcfce7;color:#166534}.bad{background:#fee2e2;color:#991b1b}.card{background:#fff;border:1px solid #e6ebf1;border-radius:17px;padding:17px;box-shadow:0 7px 24px rgba(15,23,42,.04);margin-bottom:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.item{padding:12px;background:#f8fafc;border-radius:12px}.k{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#64748b;font-weight:900;margin-bottom:4px}.v{font-size:15px;font-weight:800;word-break:break-word}.links{display:grid;grid-template-columns:1fr 1fr;gap:9px}.links a{display:block;text-decoration:none;color:#172033;background:#fff;border:1px solid #dfe6ed;border-radius:12px;padding:13px;font-weight:850}.links a span{display:block;font-size:11px;color:#64748b;font-weight:700;margin-top:3px}@media(max-width:560px){.grid,.links{grid-template-columns:1fr}.head{display:block}.head .badge{margin-top:10px}}</style></head><body><main class="wrap"><a class="back" href="javascript:history.back()">← Volver</a><div id="root"><div class="card">Cargando pago…</div></div></main><script>
const root=document.getElementById('root'),q=new URLSearchParams(location.search),folio=q.get('folio');const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dt=s=>s?new Date(String(s).replace(' ','T')).toLocaleString('es-MX'):'—';const tipo=t=>({MENSUALIDAD:'Mensualidad',INSCRIPCION:'Inscripción',INTENSIVO:'Curso intensivo'}[t]||t||'');
(async()=>{try{const r=await fetch('/api/pago-detalle.php?folio='+encodeURIComponent(folio),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'No se pudo cargar');const p=d.pago;root.innerHTML=`<div class="head"><div><h1>Pago #${esc(p.folio)}</h1><div class="sub">${esc(p.sede_nombre)} · ${tipo(p.tipo)}</div></div><span class="badge ${p.estado==='VALIDO'?'ok':'bad'}">${esc(p.estado)}</span></div><section class="card"><div class="grid"><div class="item"><div class="k">Alumno</div><div class="v">${esc(p.alumno_nombre)}</div></div><div class="item"><div class="k">Importe</div><div class="v">${money(p.importe)}</div></div><div class="item"><div class="k">Método</div><div class="v">${esc(String(p.metodo).replace('_',' '))}</div></div><div class="item"><div class="k">Fecha real de pago</div><div class="v">${dt(p.fecha)}</div></div><div class="item"><div class="k">Periodo económico</div><div class="v">${esc(d.periodo_economico||'—')}</div></div><div class="item"><div class="k">Registrado por</div><div class="v">${esc(p.created_by_usuario||'—')}</div></div>${p.observacion?`<div class="item" style="grid-column:1/-1"><div class="k">Observación</div><div class="v">${esc(p.observacion)}</div></div>`:''}</div></section><section class="links"><a href="/ficha-alumno.php?id=${encodeURIComponent(p.alumno_id)}">Ver ficha de ${esc(p.alumno_nombre)}<span>Alumno relacionado</span></a>${p.intensivo_id?`<a href="/intensivo-detalle.php?id=${encodeURIComponent(p.intensivo_id)}">Ver curso intensivo<span>${esc(p.intensivo_inicio||'')} → ${esc(p.intensivo_fin||'')}</span></a>`:`<a href="/pagos.php?alumno_id=${encodeURIComponent(p.alumno_id)}">Ver pagos del alumno<span>Historial financiero relacionado</span></a>`}</section>`}catch(e){root.innerHTML='<div class="card" style="color:#991b1b">'+esc(e.message)+'</div>'}})();
</script></body></html>